from zoneinfo import ZoneInfo
ny = ZoneInfo("America/New_York")
for dt in [datetime(9999,12,31,23,59,59), datetime(1,1,1,0,0)]:
    for zone in (ny, ZoneInfo("Asia/Karachi")):
        try:
            print(dt, zone, "->", dt.replace(tzinfo=zone).astimezone(timezone.utc))
        except Exception as e:
            print(dt, zone, "->", type(e).__name__, e)
