def test_to_utc_does_not_mutate_its_argument() -> None:
    naive = datetime(2026, 9, 1, 10, 0)
    to_utc(naive, KARACHI)
    assert naive.tzinfo is None


@pytest.mark.parametrize(
    ("dt", "zone"),
    [
        # 9999-12-31 is a common "never expires" sentinel, and shifting it east
        # of UTC leaves the datetime domain. Crashing the run over one line
        # would lose every line after it.
        (datetime(9999, 12, 31, 23, 59, 59), NEW_YORK),
        (datetime(1, 1, 1, 0, 0), KARACHI),
        (datetime(9999, 12, 31, 23, 59, 59, tzinfo=timezone(timedelta(hours=-5))), UTC),
        (datetime(1, 1, 1, 0, 0, tzinfo=timezone(timedelta(hours=5))), UTC),
    ],
)
def test_a_timestamp_utc_cannot_express_is_none(dt: datetime, zone: tzinfo) -> None:
    assert to_utc(dt, zone) is None


def test_the_domain_edges_still_convert_when_they_fit() -> None:
    assert to_utc(datetime(9999, 12, 31, 23, 59, 59), KARACHI) == datetime(
        9999, 12, 31, 18, 59, 59, tzinfo=UTC
    )

